  'Servicio de apoyo financiero para el mantenimiento y conservacion de los bancos de germoplasma',
  'Aporte financiero para la administración, el mantenimiento, y la conservación de los bancos de germoplasma animal, vegetal y microorganismos de interés agropecuario de propiedad de la nación colombiana, en cabeza del instituto colombiano Agropecuario ICA.  Lo anterior se fundamenta en la Decisión 391 de 1996 de la Comunidad Andina de Naciones sobre Régimen Común de Acceso a los Recursos Genéticos; La Ley 29 de 1990; La Ley 165 de 1994; El Decreto extraordinario 393 de 1991; Decreto 4765 de 2008.',
