  'Contempla actividades de apoyo, necesarias para el diseño e implementación de sistemas de gestión y de desempeño institucional en el marco del Modelo Integrado de Planeación y Gestión - MIPG, para generar capacidades instaladas en los servidores públicos en temas como: Fortalecimiento Institucional, Planeación Estratégica, simplificación de procesos, identificación y manejo de riesgos, controles, diseño e implementación de indicadores de gestión y gestión del conocimiento.',
