  '1999013',
  'Sedes restauradas',
  'Corresponde a un inmueble sobre el cual se adelantan obras tendientes a recuperarlo y adaptarlo, con el fin de conservar y revelar sus valores estéticos, históricos y simbólicos. Incluye las liberaciones o demoliciones parciales de agregados de los bienes de interés cultural aprobadas por parte de la autoridad competente en los anteproyectos que autoricen su intervención. (Corresponde a la licencia de construcción por restauración)',
