  'Es el conjunto de acciones, procedimientos e intervenciones integrales, mediante los cuales se orienta a la población acerca de hábitos saludables que mejoran su condición de salud.',
  NULL,
  108,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  4461,
  'S',
  '1905027',
  'Servicio de gestión del riesgo para enfermedades inmunoprevenibles',
  'Acciones relacionadas con la prevención, control y mitigación de los riesgos que propician la aparición de las enfermedades prevenibles por vacunas y sus consecuentes efectos negativos en la población.',
  NULL,
  108,
