INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  4462,
  'S',
  '1905026',
  'Servicio de gestión del riesgo para enfermedades emergentes, reemergentes y desatendidas',
  'Acciones relacionadas con la prevención y mitigación de riesgos producidos por enfermedades transmitidas por vía aérea y de contacto directo, enfermedades re-emergentes y desatendidas, enfermedades generadas por patógenos y condiciones nuevas.',
  NULL,
  108,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
