INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  4463,
  'S',
  '1905024',
  'Servicio de gestión del riesgo para abordar situaciones de salud relacionadas con condiciones ambientales',
  'Incluye la gestión integral relacionada con la prevención de enfermedades generadas por sustancias químicas, por animales (zoonosis), vectores de contaminación en el aire y el agua, entre otros factores.',
  NULL,
  108,
