INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  4464,
  'S',
  '1905021',
  'Servicio de gestión del riesgo en temas de salud sexual y reproductiva',
  'Acciones relacionadas con la prevención y mitigación de riesgos que afectan la salud sexual y reproductiva de las personas en el curso de su vida.',
  NULL,
  108,
  NULL,
  NULL,
  NULL,
  'N',
