INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  4465,
  'S',
  '1905035',
  'Servicio de gestión territorial para atención en salud -pandemias- a población afectada por emergencias o desastres',
  'Corresponde a la estrategia de respuesta en materia de salud para la población afectada ante declaratoria de situaciones de emergencias o desastres. Incluye acciones  salud pública, como medidas sanitarias , apoyo a la  prestación de servicios, para la  detección temprana, el control y la atención ante el coronavirus (Cov-19) y la implementación de los planes de preparación y respuesta ante este riesgo . Incluyen por ejemplo, según la competencia de la Entidad territorial,  apoyo a la vigilancia,  control y seguimiento epidemiológico, apoyo a la atención domiciliaria, la atención médica integral en Instituciones Prestadoras de Servicios de Salud (hospitales o Laboratorios) acondicionamiento de  albergues, el transporte de pacientes, el suministro de medicamentos e insumos, la vigilancia y el control epidemiológico. Lo anterior en articulación con las demás entidades competentes del Sistema General de Seguridad Social en salud, en especial EPS e IPS.',
  NULL,
  108,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');

